// Package agentimport imports a coding agent's pre-existing local transcripts
// into Entire as read-only, commit-less checkpoints on the v1 metadata branch.
//
// The orchestration (discovery loop, idempotent per-turn IDs, redaction, and
// the checkpoint write) is agent-agnostic and lives here. Each agent plugs in
// an Importer that knows where its transcripts live and how to split one into
// per-user-prompt turns. Claude Code is the only implementation today
// (see claude.go); others register themselves the same way.
package agentimport

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"sort"
	"time"

	"github.com/go-git/go-git/v6"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	cp "github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/entireio/cli/redact"
)

// LookbackDays bounds how far back import reaches. Fixed this pass (no flag).
const LookbackDays = 30

// SessionFile is one discovered agent transcript for a repo.
type SessionFile struct {
	Path      string // absolute path to the transcript file
	SessionID string // agent session id (used in checkpoint metadata)
}

// Turn is one user-prompt turn extracted from a session transcript. Line
// offsets are in raw-line space (newline-counted), matching transcript slicing
// and the agent token-usage helpers.
type Turn struct {
	LineStart, LineEnd int
	UUID               string
	Prompt, Model      string
	CreatedAt          time.Time
	// Tokens is this turn's token usage. Every field is a per-turn delta:
	// main-agent fields are scoped to the turn's [LineStart, LineEnd) slice by
	// the token helpers, and SubagentTokens is rescoped from the cumulative
	// snapshot those helpers return to a per-turn increment by
	// rescopeSubagentTokensToDeltas (see linesplit.go). That invariant lets
	// callers sum turns freely: writeSessionState sums them for the session
	// total and each imported checkpoint stores its own turn's delta, so a
	// subagent's tokens are counted exactly once rather than re-added on every
	// turn after it is discovered.
	Tokens *types.TokenUsage
}

// Importer is the per-agent seam: it locates an agent's transcripts for a repo
// and splits one into per-turn units. Everything else (idempotency, redaction,
// writing) is handled generically by Run.
type Importer interface {
	// Name is the registry key and the provenance source (e.g. "claude-code").
	Name() string
	// AgentType is the display name stored in checkpoint metadata (e.g. "Claude Code").
	AgentType() types.AgentType
	// Discover returns the agent's transcript files for the repo within the
	// lookback window. overridePath replaces the default transcript dir;
	// sessionFilter, when non-empty, keeps only matching session IDs.
	Discover(repoRoot, overridePath string, now time.Time, sessionFilter []string) ([]SessionFile, error)
	// SplitTurns splits one session's raw transcript bytes into per-turn units.
	SplitTurns(sf SessionFile, full []byte) ([]Turn, error)
}

// importers is the static set of supported agents. Adding an agent is a new
// Importer implementation appended here — no init() / runtime registration.
var importers = []Importer{
	claudeImporter{},
	cursorImporter{},
	piImporter{},
	factoryImporter{},
	codexImporter{},
	copilotImporter{},
	geminiImporter{},
}

// All returns every supported importer, sorted by name.
func All() []Importer {
	out := append([]Importer(nil), importers...)
	sort.Slice(out, func(i, j int) bool { return out[i].Name() < out[j].Name() })
	return out
}

// Options configures an import run.
type Options struct {
	RepoRoot      string
	OverridePath  string
	SessionFilter []string
	Now           time.Time
	DryRun        bool
}

// Result summarizes an import run.
type Result struct {
	SessionsScanned int
	TurnsImported   int
	TurnsSkipped    int
}

// DeriveCheckpointID produces a stable 12-hex checkpoint ID for an imported
// turn. Re-importing the same (sessionID, turnUUID) yields the same ID, which
// is how import stays idempotent.
func DeriveCheckpointID(sessionID, turnUUID string) id.CheckpointID {
	sum := sha256.Sum256([]byte(sessionID + "/" + turnUUID))
	return id.MustCheckpointID(hex.EncodeToString(sum[:6])) // 6 bytes = 12 lowercase hex chars
}

// Run imports the given agent's transcripts (within the lookback window) as
// read-only checkpoints on the v1 metadata branch (Kind "imported"). It is
// idempotent: turns whose deterministic ID already exists are skipped.
func Run(ctx context.Context, repo *git.Repository, imp Importer, opts Options) (Result, error) {
	var res Result
	files, err := imp.Discover(opts.RepoRoot, opts.OverridePath, opts.Now, opts.SessionFilter)
	if err != nil {
		return res, fmt.Errorf("discover %s sessions: %w", imp.Name(), err)
	}

	stores, err := cp.Open(ctx, repo, cp.OpenOptions{})
	if err != nil {
		return res, fmt.Errorf("open checkpoint store: %w", err)
	}
	existing := make(map[string]bool)
	if infos, listErr := stores.Persistent.List(ctx); listErr == nil {
		for _, in := range infos {
			existing[in.CheckpointID.String()] = true
		}
	}

	for _, sf := range files {
		res.SessionsScanned++
		full, readErr := os.ReadFile(sf.Path)
		if readErr != nil {
			return res, fmt.Errorf("read %s: %w", sf.Path, readErr)
		}
		turns, splitErr := imp.SplitTurns(sf, full)
		if splitErr != nil {
			return res, fmt.Errorf("split %s session %s: %w", imp.Name(), sf.SessionID, splitErr)
		}
		// Redact the session transcript once and reuse it for every turn's
		// checkpoint (each turn stores the full session transcript with its own
		// CheckpointTranscriptStart). Redacting per turn would be O(turns).
		// Computed lazily so a fully-skipped or dry-run file pays nothing.
		var red redact.RedactedBytes
		redacted := false
		for _, turn := range turns {
			cid := DeriveCheckpointID(sf.SessionID, turn.UUID)
			if existing[cid.String()] {
				res.TurnsSkipped++
				continue
			}
			if opts.DryRun {
				res.TurnsImported++ // counts what would import
				continue
			}
			if !redacted {
				r, rerr := redact.JSONLBytes(full)
				if rerr != nil {
					return res, fmt.Errorf("redact %s transcript: %w", sf.SessionID, rerr)
				}
				red = r
				redacted = true
			}
			if err := writeTurn(ctx, stores, imp, cid, sf, red, turn); err != nil {
				return res, err
			}
			existing[cid.String()] = true
			res.TurnsImported++
		}

		// Track A: surface this session in `entire session list`. Best-effort —
		// the read-only checkpoints above are the primary artifact, so a
		// state-write failure must not abort the import.
		if !opts.DryRun {
			if serr := writeSessionState(ctx, imp, sf, turns); serr != nil {
				logging.Debug(ctx, "import: failed to write imported session state",
					"sessionID", sf.SessionID, "error", serr.Error())
			}
		}
	}
	return res, nil
}

// writeSessionState upserts a local session.State so an imported session shows
// up in `entire session list`. It is Kind-gated (KindImported), never sets
// BaseCommit (imports are commit-less and must not be pinned to HEAD), and uses
// the transcript's own timestamps — the forward-compat contract that keeps a
// later commit-SHA link purely additive. It never clobbers a live or
// manually-attached session that happens to share the ID.
func writeSessionState(ctx context.Context, imp Importer, sf SessionFile, turns []Turn) error {
	if len(turns) == 0 {
		return nil
	}
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return fmt.Errorf("open session state store: %w", err)
	}
	if existing, lerr := store.Load(ctx, sf.SessionID); lerr == nil && existing != nil &&
		!existing.Kind.IsImported() {
		return nil // don't overwrite a real (live/attached) session
	}

	var started, ended time.Time
	var tokens *types.TokenUsage
	model := ""
	for _, turn := range turns {
		if !turn.CreatedAt.IsZero() {
			if started.IsZero() || turn.CreatedAt.Before(started) {
				started = turn.CreatedAt
			}
			if turn.CreatedAt.After(ended) {
				ended = turn.CreatedAt
			}
		}
		if turn.Model != "" {
			model = turn.Model
		}
		// turn.Tokens holds per-turn deltas for every field, including
		// SubagentTokens (rescoped from a cumulative snapshot in
		// rescopeSubagentTokensToDeltas — see the Turn.Tokens doc). Summing
		// them therefore yields the correct session total: main-agent fields
		// add up, and the subagent deltas sum back to the final cumulative
		// subagent snapshot exactly once instead of being multiplied by the
		// number of turns after each subagent was first discovered.
		tokens = types.AddTokenUsage(tokens, turn.Tokens)
	}
	if started.IsZero() {
		// No usable per-turn timestamps (some Codex lines): fall back to the
		// transcript file mtime so the row still sorts sensibly. Never "now".
		if fi, statErr := os.Stat(sf.Path); statErr == nil {
			started = fi.ModTime()
			ended = started
		}
	}
	state := &session.State{
		SessionID:           sf.SessionID,
		Kind:                session.KindImported,
		AgentType:           imp.AgentType(),
		ModelName:           model,
		StartedAt:           started,
		EndedAt:             &ended,
		Phase:               session.PhaseEnded,
		LastInteractionTime: &ended,
		StepCount:           len(turns),
		TokenUsage:          tokens,
		LastPrompt:          session.TruncatePromptForStorage(turns[len(turns)-1].Prompt),
		LastCheckpointID:    DeriveCheckpointID(sf.SessionID, turns[len(turns)-1].UUID),
	}
	if err := store.Save(ctx, state); err != nil {
		return fmt.Errorf("save imported session state %s: %w", sf.SessionID, err)
	}
	return nil
}

func writeTurn(ctx context.Context, stores *cp.Stores, imp Importer, cid id.CheckpointID, sf SessionFile, red redact.RedactedBytes, turn Turn) error {
	if err := stores.Persistent.Write(ctx, cp.Session(cp.WriteOptions{
		CheckpointID:              cid,
		SessionID:                 sf.SessionID,
		CreatedAt:                 turn.CreatedAt,
		Strategy:                  "import",
		Kind:                      string(session.KindImported),
		Agent:                     imp.AgentType(),
		Model:                     turn.Model,
		Transcript:                red,
		Prompts:                   []string{turn.Prompt},
		CheckpointsCount:          1,
		CheckpointTranscriptStart: turn.LineStart,
		TokenUsage:                turn.Tokens,
	})); err != nil {
		return fmt.Errorf("write imported checkpoint %s: %w", cid, err)
	}
	return nil
}

// Package id provides the CheckpointID type for identifying checkpoints.
// This is a separate package to avoid import cycles between paths, trailers, and checkpoint.
package id

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"regexp"

	ulid "github.com/oklog/ulid/v2"
)

// CheckpointID identifies a checkpoint. It comes in two formats: a legacy
// 12-character lowercase hex ID and a 26-character Crockford base32 ULID (see
// Kind / CheckpointPattern). It links code commits to their checkpoint metadata.
//
//nolint:recvcheck // UnmarshalJSON requires pointer receiver, others use value receiver - standard pattern
type CheckpointID string

// EmptyCheckpointID represents an unset or invalid checkpoint ID.
const EmptyCheckpointID CheckpointID = ""

// Pattern is the regex pattern for a legacy checkpoint ID: exactly 12 lowercase
// hex characters. Exported for use in other packages (e.g., trailers) to avoid
// pattern duplication. It is also reused by investigate/provenance for *run IDs*,
// which are always 12-hex — do NOT widen this to include ULIDs; use
// CheckpointPattern for matching a checkpoint ID that may be either format.
const Pattern = `[0-9a-f]{12}`

// ulidPattern is the regex SHAPE of a ULID checkpoint ID: 26 Crockford base32
// characters (digits plus uppercase A-Z excluding I, L, O, U). It exists only to
// compose CheckpointPattern for extracting a candidate ID from free text; it is
// deliberately NOT exported and NOT the validator. Authoritative validation
// decodes the value via oklog/ulid (see KindOf/isULID), which additionally
// rejects e.g. a timestamp overflow the char class alone would accept.
const ulidPattern = `[REDACTED]{26}`

// CheckpointPattern matches a checkpoint ID in free text in either format
// (legacy 12-hex or ULID). Use this — not Pattern — when scanning text such as
// the Entire-Checkpoint commit trailer for a candidate checkpoint ID, then
// validate the captured token via NewCheckpointID/Validate (CheckpointPattern is
// a loose shape, not authoritative validation).
const CheckpointPattern = `(?:` + Pattern + `|` + ulidPattern + `)`

// prefixShapeRegex matches strings shaped like a checkpoint ID or a prefix of
// one: 1-12 lowercase hex characters (legacy) or 1-26 Crockford base32
// characters starting with 0-7 (a ULID's leading timestamp character cannot
// exceed 7, per isULID/ParseStrict). Kept next to Pattern/ulidPattern as a
// reminder to update them together when the ID formats change.
var prefixShapeRegex = regexp.MustCompile(`^(?:[0-9a-f]{1,12}|[0-7][REDACTED]{0,25})$`)

// CouldBePrefix reports whether s is shaped like a checkpoint ID or a prefix
// of one. It is a cheap gate for callers deciding whether a free-form target
// could name a checkpoint before paying for a store lookup; it is not
// validation (see Validate).
func CouldBePrefix(s string) bool {
	return prefixShapeRegex.MatchString(s)
}

// ShortIDLength is the standard length for truncating IDs for display purposes.
// Used for tool use IDs, session IDs, and commit hashes in logs and messages.
const ShortIDLength = 12

// MaxIDLength is the longest a valid checkpoint ID can be — a 26-character ULID.
// Use it (not ShortIDLength) when reasoning about whether a string could be a
// checkpoint ID or a prefix of one, since IDs are no longer fixed-width. Tied to
// oklog/ulid's own encoded-size constant so the three ULID-width sites (this,
// ulidPattern's {26}, and the library) cannot drift apart.
const MaxIDLength = ulid.EncodedSize

// checkpointIDRegex validates the legacy format: exactly 12 lowercase hex characters.
var checkpointIDRegex = regexp.MustCompile(`^` + Pattern + `$`)

// isULID reports whether s is a ULID in canonical form, decoded via oklog/ulid —
// the same library that will generate ULIDs — so validation and generation agree
// by construction. ParseStrict enforces the 26-char length, the Crockford
// alphabet, and the timestamp-overflow bound (first character must be 0-7). The
// round-trip (v.String() == s) additionally requires the canonical uppercase
// encoding: it rejects lowercase and Crockford-normalized aliases (e.g. I/L→1,
// O→0) that ParseStrict would otherwise accept but we never emit.
func isULID(s string) bool {
	v, err := ulid.ParseStrict(s)
	return err == nil && v.String() == s
}

// Kind classifies a checkpoint ID by its format: legacy 12-hex or ULID.
type Kind int

const (
	// KindUnknown is a string matching neither the legacy hex nor the ULID format.
	KindUnknown Kind = iota
	// KindLegacy is a 12-character lowercase hex ID (the format Generate emits).
	KindLegacy
	// KindULID is a 26-character Crockford base32 ULID.
	KindULID
)

// KindOf classifies a checkpoint ID string. It does not error: an unrecognized
// string is KindUnknown, which callers handle conservatively.
func KindOf(s string) Kind {
	switch {
	case checkpointIDRegex.MatchString(s):
		return KindLegacy
	case isULID(s):
		return KindULID
	default:
		return KindUnknown
	}
}

// Kind classifies this checkpoint ID.
func (id CheckpointID) Kind() Kind {
	return KindOf(string(id))
}

// ShardFor returns the two-character shard for storing this ID under a
// per-checkpoint git ref (refs/entire/checkpoints/<shard>/<id>): the LAST two
// characters of the ID, for BOTH supported formats.
//
// A single positional rule (independent of the ID's Kind) keeps ref naming
// robust for legacy and ULID IDs alike and impossible to compute inconsistently
// between callers. The suffix spreads checkpoints evenly across buckets for
// either format: a legacy hex ID is random throughout, and a ULID's leading
// characters encode its timestamp (barely varying between nearby checkpoints)
// while its trailing characters are random — so sharding on the suffix keeps the
// distribution even while the ID itself stays lexicographically sortable.
//
// This is the git-refs ref namespace only; the entire/checkpoints/v1 branch tree
// keeps its own independent first-two layout (see Path). For an ID shorter than
// two characters the whole ID is returned.
func (id CheckpointID) ShardFor() string {
	s := string(id)
	if len(s) < 2 {
		return s
	}
	return s[len(s)-2:]
}

// NewCheckpointID creates a CheckpointID from a string, validating its format.
// Returns an error unless the string is a valid checkpoint ID (12-char hex or ULID).
func NewCheckpointID(s string) (CheckpointID, error) {
	if err := Validate(s); err != nil {
		return EmptyCheckpointID, err
	}
	return CheckpointID(s), nil
}

// MustCheckpointID creates a CheckpointID from a string, panicking if invalid.
// Use only when the ID is known to be valid (e.g., from trusted sources).
func MustCheckpointID(s string) CheckpointID {
	id, err := NewCheckpointID(s)
	if err != nil {
		panic(err)
	}
	return id
}

// Generate creates a new random 12-character hex checkpoint ID.
//
// Generation stays 12-hex regardless of storage backend. Emitting ULIDs is a
// separate, store-coupled change (new checkpoints get a ULID only under the
// git-refs store); this package only recognizes/validates both formats.
func Generate() (CheckpointID, error) {
	bytes := make([]byte, 6) // 6 bytes = 12 hex chars
	if _, err := rand.Read(bytes); err != nil {
		return EmptyCheckpointID, fmt.Errorf("failed to generate random checkpoint ID: %w", err)
	}
	return CheckpointID(hex.EncodeToString(bytes)), nil
}

// GenerateULID creates a new 26-character Crockford base32 ULID checkpoint ID:
// a millisecond timestamp prefix plus crypto-random entropy, so IDs are unique
// and lexicographically time-sortable. It is the format the git-refs store uses
// (chosen by checkpoint.GenerateCheckpointID); the value is canonical and passes
// KindOf/Validate as KindULID.
//
// The timestamp is Unix epoch milliseconds (via ulid.Now), so it is inherently
// timezone-independent — the machine's local zone does not affect the ID.
func GenerateULID() (CheckpointID, error) {
	u, err := ulid.New(ulid.Now(), rand.Reader)
	if err != nil {
		return EmptyCheckpointID, fmt.Errorf("failed to generate ULID checkpoint ID: %w", err)
	}
	return CheckpointID(u.String()), nil
}

// Validate checks if a string is a valid checkpoint ID format: either a legacy
// 12-character lowercase hex ID or a 26-character Crockford base32 ULID.
// Returns an error if invalid, nil if valid.
func Validate(s string) error {
	if KindOf(s) == KindUnknown {
		return fmt.Errorf("invalid checkpoint ID %q: must be 12 lowercase hex characters or a 26-character ULID", s)
	}
	return nil
}

// String returns the checkpoint ID as a string.
func (id CheckpointID) String() string {
	return string(id)
}

// DisplayShort returns the checkpoint ID trimmed for compact display. A legacy
// hex ID is random throughout, so its ShortIDLength-char prefix identifies it and
// resolves as a prefix. A ULID encodes a millisecond timestamp in its leading
// characters (near-identical for checkpoints minted close in time) with entropy
// only in the tail, so a front-truncated ULID is both ambiguous and misleading —
// it looks like a complete ID but won't resolve — so a ULID is returned in full.
// Non-ID strings (e.g. "temporary") are trimmed like the legacy case.
func (id CheckpointID) DisplayShort() string {
	s := string(id)
	if KindOf(s) == KindULID {
		return s
	}
	if len(s) > ShortIDLength {
		return s[:ShortIDLength]
	}
	return s
}

// IsEmpty returns true if the checkpoint ID is empty or unset.
func (id CheckpointID) IsEmpty() bool {
	return id == EmptyCheckpointID
}

// Path returns the sharded path for this checkpoint ID on entire/checkpoints/v1.
// Uses first 2 characters as shard (256 buckets), remaining as folder name.
// Example: "a3b2c4d5e6f7" -> "a3/b2c4d5e6f7"
func (id CheckpointID) Path() string {
	if len(id) < 3 {
		return string(id)
	}
	return string(id[:2]) + "/" + string(id[2:])
}

// MarshalJSON implements json.Marshaler.
func (id CheckpointID) MarshalJSON() ([]byte, error) {
	data, err := json.Marshal(string(id))
	if err != nil {
		return nil, fmt.Errorf("failed to marshal checkpoint ID: %w", err)
	}
	return data, nil
}

// UnmarshalJSON implements json.Unmarshaler with validation.
// Returns an error unless the JSON string is a valid checkpoint ID (12-char hex
// or ULID). Empty strings are allowed and result in EmptyCheckpointID.
func (id *CheckpointID) UnmarshalJSON(data []byte) error {
	var s string
	if err := json.Unmarshal(data, &s); err != nil {
		return fmt.Errorf("failed to unmarshal checkpoint ID: %w", err)
	}
	// Allow empty strings (represents unset checkpoint ID)
	if s == "" {
		*id = EmptyCheckpointID
		return nil
	}
	if err := Validate(s); err != nil {
		return err
	}
	*id = CheckpointID(s)
	return nil
}

